pub use c6_core::unit;
#[path="crates/c6-core/src/player_espionage.rs"]pub mod espionage;
#[path="crates/c6-core/src/player_religion.rs"]pub mod religion;
#[path="crates/c6-core/src/player_resources.rs"]pub mod resources;
use c6_core::{core_stream::ThroughFirstPlayer,map};use std::io::{Read,Write};
fn main(){let mut input=vec![];std::io::stdin().read_to_end(&mut input).unwrap();let v=ThroughFirstPlayer::decode(&input,map::Limits::default(),unit::Limits::default()).unwrap();let mut pos=v.consumed;let mut items=v.items_used;
let(e,en,ei)=espionage::Espionage::decode_prefix_with_items(&input[pos..],unit::Limits{max_bytes:map::Limits::default().max_bytes-pos,max_items:map::Limits::default().max_items-items}).unwrap();pos+=en;items+=ei;
let(r,rn,ri)=religion::Religion::decode_prefix_with_items(&input[pos..],unit::Limits{max_bytes:map::Limits::default().max_bytes-pos,max_items:map::Limits::default().max_items-items}).unwrap();pos+=rn;items+=ri;
let(s,sn,si)=resources::Resources::decode_prefix_with_items(&input[pos..],unit::Limits{max_bytes:map::Limits::default().max_bytes-pos,max_items:map::Limits::default().max_items-items}).unwrap();pos+=sn;items+=si;
let(mut out,pi)=v.player_prefix.encode_prefix_with_items(unit::Limits::default()).unwrap();let mut write_items=pi;for(b,i)in[e.encode_with_items(unit::Limits::default()).unwrap(),r.encode_with_items(unit::Limits::default()).unwrap(),s.encode_with_items(unit::Limits::default()).unwrap()]{out.extend(b);write_items+=i;}assert_eq!(out,input[v.core.consumed..pos]);assert_eq!(write_items,items-v.core.items_used);
println!("{} {} {} {} {} {} {} {} {} {} {} {}",v.core.consumed,pos,items,write_items,en,ei,rn,ri,sn,si,input.len()-pos,r.faith_balance_q8);std::io::stdout().write_all(&out).unwrap();}

