use c6_core::{core_stream::ThroughFirstPlayer,core_player::Boundary,map,unit};
use std::io::{Read,Write};
fn main(){
 let mut input=Vec::new();std::io::stdin().read_to_end(&mut input).unwrap();
 let v=ThroughFirstPlayer::decode(&input,map::Limits::default(),unit::Limits::default()).unwrap();
 assert_eq!(v.player_prefix.boundary,Boundary::PlayerTreasury);
 assert_eq!(v.tail,&input[v.consumed..]);assert!(std::ptr::eq(v.tail.as_ptr(),input[v.consumed..].as_ptr()));
 let(encoded,post_items)=v.player_prefix.encode_prefix_with_items(unit::Limits::default()).unwrap();
 assert_eq!(encoded,input[v.core.consumed..v.consumed]);assert_eq!(v.items_used,v.core.items_used+post_items);
 let p=v.player_prefix.first_player.as_ref().unwrap();
 let parts=[p.espionage.encode_with_items(unit::Limits::default()).unwrap(),p.religion.encode_with_items(unit::Limits::default()).unwrap(),p.resources.encode_with_items(unit::Limits::default()).unwrap(),p.stats.encode_with_items(unit::Limits::default()).unwrap(),p.techs.encode_with_items(unit::Limits::default()).unwrap()];
 let resources_end=v.consumed-parts[3].0.len()-parts[4].0.len();
 let religion_end=resources_end-parts[2].0.len();let espionage_end=religion_end-parts[1].0.len();let culture_end=espionage_end-parts[0].0.len();let stats_end=v.consumed-parts[4].0.len();
 let shared=map::Limits{max_bytes:v.consumed,max_items:v.items_used,max_allocation:v.core.logical_allocation_used,..map::Limits::default()};
 let player=unit::Limits{max_bytes:encoded.len(),max_items:post_items};
 assert!(ThroughFirstPlayer::decode(&input,shared,player).is_ok());
 for s in[map::Limits{max_bytes:shared.max_bytes-1,..shared},map::Limits{max_items:shared.max_items-1,..shared}]{assert!(ThroughFirstPlayer::decode(&input,s,player).is_err());}
 for l in[unit::Limits{max_bytes:player.max_bytes-1,..player},unit::Limits{max_items:player.max_items-1,..player}]{assert!(ThroughFirstPlayer::decode(&input,shared,l).is_err());}
 for cut in[v.core.consumed,culture_end,espionage_end,religion_end,resources_end,stats_end,v.consumed-1]{assert!(ThroughFirstPlayer::decode(&input[..cut],map::Limits::default(),unit::Limits::default()).is_err());}
 let(out,ei)=v.player_prefix.encode_prefix_with_items(player).unwrap();assert_eq!(out,encoded);assert_eq!(ei,post_items);
 for l in[unit::Limits{max_bytes:player.max_bytes-1,..player},unit::Limits{max_items:player.max_items-1,..player}]{assert!(v.player_prefix.encode_prefix_with_items(l).is_err());}
 let mut fields=vec![v.core.consumed,v.consumed,v.items_used,post_items,v.tail.len(),resources_end,culture_end,espionage_end,religion_end,stats_end,v.player_prefix.unfinished_player_entries as usize,usize::from(p.header.saved_is_alive()),v.core.logical_allocation_used];
 for(b,i)in &parts{fields.push(b.len());fields.push(*i);}
 println!("{}",fields.iter().map(usize::to_string).collect::<Vec<_>>().join(" "));std::io::stdout().write_all(&encoded).unwrap();
}
